def make_floor():
 # Three complete finite scene-support solids. Curved shelf rear penetrates screen by6mm.
 ts=[]
 def triangulate(p):
  cross2=lambda a,b,c:(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])
  order=list(range(len(p)));out=[]
  if sum(a[0]*b[1]-a[1]*b[0]for a,b in zip(p,p[1:]+p[:1]))<0:order.reverse()
  while len(order)>3:
   for k,b in enumerate(order):
    a,c=order[k-1],order[(k+1)%len(order)]
    if cross2(p[a],p[b],p[c])<=1e-14:continue
    if any(min(cross2(p[a],p[b],p[j]),cross2(p[b],p[c],p[j]),cross2(p[c],p[a],p[j]))>=-1e-14 for j in order if j not in[a,b,c]):continue
    out.append((a,b,c));order.pop(k);break
   else:raise AssertionError('Untriangulable scene outline')
  return out+[tuple(order)]
 def prism(p,z0,z1,mat):
  if sum(a[0]*b[1]-a[1]*b[0]for a,b in zip(p,p[1:]+p[:1]))<0:p=list(reversed(p))
  v=[(x,y,z)for z in[z0,z1]for x,y in p];n=len(p);tri=triangulate(p);faces=[tuple(reversed(t))for t in tri]+[tuple(n+i for i in t)for t in tri]+[(i,(i+1)%n,(i+1)%n+n,i+n)for i in range(n)]
  for f in faces:
   for k in range(1,len(f)-1):ts.append(((v[f[0]],v[f[k]],v[f[k+1]]),mat))
 prism([(-.225,-.215),(.225,-.215),(.245,-.195),(.245,.195),(.225,.215),(-.225,.215),(-.245,.195),(-.245,-.195)],0,.016,0)
 aa=[math.radians(35+110*i/32)for i in range(33)]
 crescent=[(.283*math.cos(a),-.08+.283*math.sin(a))for a in aa]+[(.270*math.cos(a),-.08+.270*math.sin(a))for a in reversed(aa)]
 prism(crescent,.015,.195,1)
 angle=math.acos(.160/.276);arc=[angle+(math.pi-2*angle)*i/24 for i in range(25)]
 shelf=[(-.160,.080),(.160,.080)]+[(.276*math.cos(a),-.08+.276*math.sin(a))for a in arc]
 prism(shelf,.153,.165,0)
 mats=[{'name':n,'doubleSided':True,'pbrMetallicRoughness':{'baseColorFactor':color,'metallicFactor':0.,'roughnessFactor':rough}}for n,color,rough in [('ScenePaleCompleteDeckAndCurvedEdgeShelf',[.55,.50,.43,1],.78),('SceneMutedTealContinuousCurvedBackScreen',[.15,.27,.28,1],.72)]]
 return ts,mats

